use strict; use warnings; use utf8; use IO::Socket::INET; use LWP::UserAgent;
binmode STDOUT, ':encoding(UTF-8)';
sub number_to_words { my($n)=@_; my $body="<?xml version=\"1.0\" encoding=\"utf-8\"?><soap:Envelope xmlns:soap=\"http://schemas.xmlsoap.org/soap/envelope/\"><soap:Body><NumberToWords xmlns=\"http://www.dataaccess.com/webservicesserver/\"><ubiNum>$n</ubiNum></NumberToWords></soap:Body></soap:Envelope>"; my $ua=LWP::UserAgent->new; my $res=$ua->post('https://www.dataaccess.com/webservicesserver/NumberConversion.wso','Content-Type'=>'text/xml; charset=utf-8','SOAPAction'=>'http://www.dataaccess.com/webservicesserver/NumberToWords',Content=>$body); my $xml=$res->decoded_content; $xml =~ /<m:NumberToWordsResult>(.*?)<\/m:NumberToWordsResult>|<NumberToWordsResult>(.*?)<\/NumberToWordsResult>/s; return $1 || $2 || $xml; }
sub translate { my($t)=@_; my %d=('zero'=>'cero','one'=>'uno','two'=>'dos','three'=>'tres','four'=>'cuatro','five'=>'cinco','six'=>'seis','seven'=>'siete','eight'=>'ocho','nine'=>'nueve','ten'=>'diez','eleven'=>'once','twelve'=>'doce','thirteen'=>'trece','fourteen'=>'catorce','fifteen'=>'quince','sixteen'=>'dieciseis','seventeen'=>'diecisiete','eighteen'=>'dieciocho','nineteen'=>'diecinueve','twenty'=>'veinte','thirty'=>'treinta','forty'=>'cuarenta','fifty'=>'cincuenta','sixty'=>'sesenta','seventy'=>'setenta','eighty'=>'ochenta','ninety'=>'noventa','hundred'=>'cien','thousand'=>'mil','million'=>'millon','millions'=>'millones','and'=>'y'); $t=lc($t); for my $k (keys %d){$t=~s/$k/$d{$k}/g;} return $t; }
my $server=IO::Socket::INET->new(LocalPort=>3000,Listen=>5,Reuse=>1) or die $!; print "Servidor en http://localhost:3000/?n=10\n";
while(my $client=$server->accept){ my $req=<$client>; my($n)=$req=~/\?n=([0-9]+)/; $n//=10; my $out=translate(number_to_words($n)); print $client "HTTP/1.1 200 OK\r\nContent-Type: text/plain; charset=utf-8\r\n\r\n$out"; close $client; }
